/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field Price.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModulePrice extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, Price);
}

public Set getAllowedValues()
{
    InventTableModule   inventTableModule;
    var                 ret = new Set(Types::Real);

    while select Price from inventTableModule
        group by Price
    {
        if (!ret.in(inventTableModule.Price))
        {
            ret.add(inventTableModule.Price);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, Price));
    qbr.value(queryValue(_value));
}
